CREATE TABLE IF NOT EXISTS gis_data_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, provider_type text NOT NULL, authority_name text, jurisdiction_code text, source_url text, service_type text, license_text text, provenance_notes text, refresh_policy text NOT NULL DEFAULT 'Manual', last_checked_at timestamptz, next_refresh_at timestamptz, reliability_score numeric(6,2), status text NOT NULL DEFAULT 'Active', created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE gis_layers ADD COLUMN IF NOT EXISTS source_id uuid REFERENCES gis_data_sources(id) ON DELETE SET NULL;
ALTER TABLE gis_layers ADD COLUMN IF NOT EXISTS layer_key text;
ALTER TABLE gis_layers ADD COLUMN IF NOT EXISTS name text;
ALTER TABLE gis_layers ADD COLUMN IF NOT EXISTS geometry_type text;
ALTER TABLE gis_layers ADD COLUMN IF NOT EXISTS crs text;
ALTER TABLE gis_layers ADD COLUMN IF NOT EXISTS service_endpoint text;
ALTER TABLE gis_layers ADD COLUMN IF NOT EXISTS format text NOT NULL DEFAULT 'GeoJSON';
ALTER TABLE gis_layers ADD COLUMN IF NOT EXISTS authority_name text;
ALTER TABLE gis_layers ADD COLUMN IF NOT EXISTS jurisdiction_code text;
ALTER TABLE gis_layers ADD COLUMN IF NOT EXISTS temporal_start timestamptz;
ALTER TABLE gis_layers ADD COLUMN IF NOT EXISTS temporal_end timestamptz;
ALTER TABLE gis_layers ADD COLUMN IF NOT EXISTS confidence_score numeric(6,2);
ALTER TABLE gis_layers ADD COLUMN IF NOT EXISTS verification_status text NOT NULL DEFAULT 'Unverified';
ALTER TABLE gis_layers ADD COLUMN IF NOT EXISTS visibility text NOT NULL DEFAULT 'Private';
ALTER TABLE gis_layers ADD COLUMN IF NOT EXISTS last_ingested_at timestamptz;
ALTER TABLE gis_layers ADD COLUMN IF NOT EXISTS record_count integer NOT NULL DEFAULT 0;
ALTER TABLE gis_layers ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'Active';
UPDATE gis_layers SET layer_key=COALESCE(layer_key,layer_code), name=COALESCE(name,layer_name), status=COALESCE(status,layer_status) WHERE layer_key IS NULL OR name IS NULL OR status IS NULL;
CREATE TABLE IF NOT EXISTS gis_ingestion_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), layer_id uuid NOT NULL REFERENCES gis_layers(id) ON DELETE CASCADE, job_type text NOT NULL DEFAULT 'Import', started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, status text NOT NULL DEFAULT 'Queued', records_seen integer NOT NULL DEFAULT 0, records_accepted integer NOT NULL DEFAULT 0, records_rejected integer NOT NULL DEFAULT 0, error_summary text, provenance_snapshot text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_layer_publication_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), layer_id uuid NOT NULL REFERENCES gis_layers(id) ON DELETE CASCADE, publication_status text NOT NULL DEFAULT 'Restricted', allowed_fields text, redaction_notes text, approved_by_reference text, approved_at timestamptz, expires_at timestamptz, status text NOT NULL DEFAULT 'Active', UNIQUE(layer_id));
CREATE INDEX IF NOT EXISTS idx_gis_sources_status ON gis_data_sources(status,jurisdiction_code);
CREATE INDEX IF NOT EXISTS idx_gis_layers_jurisdiction ON gis_layers(jurisdiction_code,verification_status,visibility);
CREATE INDEX IF NOT EXISTS idx_gis_jobs_layer ON gis_ingestion_jobs(layer_id,status,started_at DESC);
CREATE INDEX IF NOT EXISTS idx_gis_publication_layer ON gis_layer_publication_rules(layer_id,publication_status);